67				holders = append(holders, placeholder(len(args)+1))
68				args = append(args, id)
69			}
70			where = append(where, "memo.id IN ("+strings.Join(holders, ", ")+")")
71		}
72		if v := find.UID; v != nil {
73			where, args = append(where, "memo.uid = "+placeholder(len(args)+1)), append(args, *v)
74		}
75		if len(find.UIDList) > 0 {
76			holders := make([]string, 0, len(find.UIDList))
77			for _, uid := range find.UIDList {
78				holders = append(holders, placeholder(len(args)+1))
79				args = append(args, uid)
80			}
81			where = append(where, "memo.uid IN ("+strings.Join(holders, ", ")+")")
82		}
83		if v := find.CreatorID; v != nil {
84			where, args = append(where, "memo.creator_id = "+placeholder(len(args)+1)), append(args, *v)
85		}
86		if v := find.RowStatus; v != nil {
87			where, args = append(where, "memo.row_status = "+placeholder(len(args)+1)), append(args, *v)
88		}
89		if v := find.VisibilityList; len(v) != 0 {
