132		query := `SELECT ` + strings.Join(fields, ", ") + `
133			FROM memo
134			LEFT JOIN "user" AS memo_creator ON memo.creator_id = memo_creator.id
135			LEFT JOIN memo_relation ON memo.id = memo_relation.memo_id AND memo_relation.type = 'COMMENT'
136			LEFT JOIN memo AS parent_memo ON memo_relation.related_memo_id = parent_memo.id
